import {
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    BooleanColumn,
    ConditionsColumn,
    Table,
    ChoiceColumn,
    BasicImageColumn,
    DecimalColumn,
    DocumentIdColumn,
    DomainIdColumn,
    DomainPathColumn,
    FieldNameColumn,
    ListColumn,
    RadioColumn,
    ScriptColumn,
    SystemClassNameColumn,
    TableNameColumn,
    TranslatedFieldColumn,
    TranslatedTextColumn,
    UserRolesColumn,
    VersionColumn,
    BasicDateTimeColumn,
    CalendarDateTimeColumn,
    DateColumn,
    DateTimeColumn,
    DueDateColumn,
    GenericColumn,
    IntegerDateColumn,
    OtherDateColumn,
    ScheduleDateTimeColumn,
} from '@servicenow/sdk/core'

export const sn_table_app_multi_column = Table({
    name: 'sn_table_app_multi_column',
    label: 'MultiColumn Table',
    schema: {
        string_column: StringColumn({ default: 'default string' }),
        boolean_column: BooleanColumn({ default: true }),
        integer_column: IntegerColumn({ default: 42 }),
        image_column: BasicImageColumn({ default: 'https://example.com/default.jpg' }),
        condition_column: ConditionsColumn({ default: 'active=true' }),
        choice_column: ChoiceColumn({
            default: 'option1',
            choices: {
                option1: 'Option 1',
                option2: 'Option 2',
                option3: 'Option 3',
            },
        }),
        decimal_column: DecimalColumn({ default: '3.14159' }),
        document_id_column: DocumentIdColumn({ default: 'document_123', dependent: 'table_name_column' }),
        reference_column: ReferenceColumn({ referenceTable: 'incident', default: 'sys_user.admin' }),
        domain_id_column: DomainIdColumn({ default: 'global' }),
        domain_path_column: DomainPathColumn({ default: '/' }),
        glide_list_column: ListColumn({ default: 'item1,item2,item3', referenceTable: 'incident' }),
        radio_column: RadioColumn({
            default: 'option_a',
            options: [
                { label: 'Option A', value: 'option_a' },
                { label: 'Option B', value: 'option_b' },
            ],
        }),
        script_column: ScriptColumn({ default: 'function() { return "default script"; }' }),
        sys_class_name_column: SystemClassNameColumn({ default: 'sys_user' }),
        table_name_column: TableNameColumn({ default: 'incident' }),
        translated_field_column: TranslatedFieldColumn({ default: 'short_description' }),
        translated_text_column: TranslatedTextColumn({ default: 'translated text' }),
        user_roles_column: UserRolesColumn({ default: ['admin', 'itil'] }),
        version_column: VersionColumn({ default: '1.0.0' }),
        field_name_column: FieldNameColumn({ default: 'description' }),
        glide_date_column: DateColumn({ default: '2025-06-02' }),
        glide_date_time_column: DateTimeColumn({ default: '2025-06-02T12:00:00-07:00' }),
        calendar_date_time_column: CalendarDateTimeColumn({ default: '2025-06-02 12:00:00' }),
        datetime_column: BasicDateTimeColumn({ default: '2025-06-02 12:00:00' }),
        due_date_column: DueDateColumn({ default: '2025-06-09 12:00:00' }),
        integer_date_column: IntegerDateColumn({ default: '20250602' }),
        schedule_date_time_column: ScheduleDateTimeColumn({ default: '0 12 * * *' }),
        date_column: OtherDateColumn({ default: '2025-06-02 12:00:00' }),
        generic_column: GenericColumn({
            columnType: 'generic',
            default: 'value',
        }),
    },
})
